pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        // the external call inside C's transfer targets a contract that must not revert
        // we deploy a helper that succeeds so the transfer function itself does not revert
        Succeeder succ = new Succeeder();
