// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        // Ensure caddress has code so the low-level call succeeds and doesn't revert
        vm.assume(caddress.code.length > 0);
        // Ensure _tos entries are not zero address, to avoid revert scenarios unrelated to the return value difference
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        // We need a helper contract that provides a successful call so the mutant reaches the return false path.
        // Deploy a simple helper that returns true on the targeted selector.
        Helper helper = new Helper();
        // Use the helper's address as caddress for the low-level call
        bool ok;
        try c.transfer(from, address(helper), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, the property does not apply (rule is about non-reverting calls)
            return;
        }
        // If the call completed, the return value must be true
        assertTrue(ok);
    }
}

contract Helper {
    // This contract simply returns true for any call to transferFrom, ensuring the low-level call succeeds.
    fallback() external payable returns (bytes memory) {
        return abi.encode(true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v > 0);
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = true;
            assertTrue(ret);
        } catch {
            ok = false;
        }
    }
}
